using Microsoft.AspNetCore.Mvc; using Exercicio09_Veterinaria.Models; namespace Exercicio09_Veterinaria.Controllers; public class VeterinariaController:Controller{private static readonly List<Animal> Dados=new(){new(){Id=1,Nome="Animal 1",Especie="Cachorro",Idade=2,Dono="Dono 1"},new(){Id=2,Nome="Animal 2",Especie="Gato",Idade=3,Dono="Dono 2"},new(){Id=3,Nome="Animal 3",Especie="Cachorro",Idade=4,Dono="Dono 3"},new(){Id=4,Nome="Animal 4",Especie="Gato",Idade=5,Dono="Dono 4"},new(){Id=5,Nome="Animal 5",Especie="Cachorro",Idade=6,Dono="Dono 5"},new(){Id=6,Nome="Animal 6",Especie="Gato",Idade=7,Dono="Dono 6"},new(){Id=7,Nome="Animal 7",Especie="Cachorro",Idade=8,Dono="Dono 7"},new(){Id=8,Nome="Animal 8",Especie="Gato",Idade=1,Dono="Dono 8"},}public IActionResult Index()=>View(Dados); public IActionResult Cachorros()=>View("Index",Dados.Where(x=>x.Especie=="Cachorro")); public IActionResult Gatos()=>View("Index",Dados.Where(x=>x.Especie=="Gato"));}
